"""Live original native owner and independently decoded API reply evidence."""
import json,os,time
from pathlib import Path
import run_decode40_host_profile_v3 as life
from serial37_canonical_json_v3 import canonical
from source43_api_evidence_v1 import require,epoch
c=life.c;HERE=life.HERE

def start_ticks(pid):
 raw=Path('/proc/'+str(pid)+'/stat').read_text();return int(raw[raw.rfind(')')+2:].split()[19])
def host_owner(root,m):
 root=Path(root);launch=c.read(root/'launch.json');obj=c.inspected(launch['container']);require(obj['Config']['Labels']['b70.c1.prepared']==launch['prepared_sha256']and obj['State']['Running']is True and type(obj['State']['Pid'])is int and obj['State']['Pid']>0,'Exact live API owner required');trace=[json.loads(line)for line in(root/'engine-token-trace.jsonl').read_text().splitlines()];pids={r['engine_pid']for r in trace if r['kind']=='engine_begin'};require(len(pids)==1,'One actual traced native PID required');native=next(iter(pids));require(type(native)is int and native>1,'Native child namespace PID required');host=obj['State']['Pid'];parent_stat_before=Path('/proc/'+str(host)+'/stat').read_text();children=Path('/proc/'+str(host)+'/task/'+str(host)+'/children').read_text();rows=[]
 for token in children.split():
  pid=int(token);stat_before=Path('/proc/'+str(pid)+'/stat').read_text();before=start_ticks(pid);status=Path('/proc/'+str(pid)+'/status').read_text();fields=[line.split()[1:]for line in status.splitlines()if line.startswith('NSpid:')];namespace=os.readlink('/proc/'+str(pid)+'/ns/pid');exe=os.readlink('/proc/'+str(pid)+'/exe');after=start_ticks(pid);rows.append({'stat_before':stat_before,'stat_after':Path('/proc/'+str(pid)+'/stat').read_text(),'host_pid':pid,'start_ticks':before,'start_ticks_after':after,'status':status,'namespace':namespace,'exe':exe,'NSpid':list(map(int,fields[0]))if len(fields)==1 else []})
 proof={'schema':2,'container_stat_before':parent_stat_before,'container_stat_after':Path('/proc/'+str(host)+'/stat').read_text(),'container':launch['container'],'container_host_pid':host,'container_start_ticks':start_ticks(host),'container_namespace':os.readlink('/proc/'+str(host)+'/ns/pid'),'container_status':Path('/proc/'+str(host)+'/status').read_text(),'children_raw':children,'children':rows,'trace_native_pid':native,'before_inspection':obj,'after_inspection':c.inspected(launch['container']),'epoch':time.time()};owner_binding(proof,m,launch);c.write(root/'native-owner.json',proof);return proof

def owner_binding(proof,m,launch):
 epoch(proof['epoch']);before=proof['before_inspection'];after=proof['after_inspection'];require(proof['schema']==2 and type(proof['schema'])is int and before['Id']==after['Id']and before['State']['Pid']==after['State']['Pid']==proof['container_host_pid']and before['State']['Running']is after['State']['Running']is True and before['Config']['Image']==after['Config']['Image']==m['runtime']['image']and before['HostConfig']['PidMode']==after['HostConfig']['PidMode']==''and before['Name']==after['Name']=='/'+launch['container']and before['Config']['Labels']['b70.c1.prepared']==after['Config']['Labels']['b70.c1.prepared']==launch['prepared_sha256'],'Exact current original live container association differs');require(type(proof['container_host_pid'])is int and type(proof['container_start_ticks'])is int and proof['container_start_ticks']>0,'Typed live owner start required');parent_before=parse_stat(proof['container_stat_before']);parent_after=parse_stat(proof['container_stat_after']);require(parent_before['pid']==parent_after['pid']==proof['container_host_pid']and parent_before['start']==parent_after['start']==proof['container_start_ticks'],'Actual parent raw PID/start association differs');parentns=[line.split()[1:]for line in proof['container_status'].splitlines()if line.startswith('NSpid:')];require(len(parentns)==1 and list(map(int,parentns[0]))==[proof['container_host_pid'],1],'Actual isolated container PID1 required');require([r['host_pid']for r in proof['children']]==list(map(int,proof['children_raw'].split())),'Exact actual child process roster');matches=[r for r in proof['children']if r['NSpid']==[r['host_pid'],proof['trace_native_pid']]];require(len(matches)==1,'Actual trace PID must join unique host child');row=matches[0];require(parse_stat(row['stat_before'])['ppid']==parse_stat(row['stat_after'])['ppid']==proof['container_host_pid'],'Actual native child parent differs');status_fields=[line.split()[1:]for line in row['status'].splitlines()if line.startswith('NSpid:')];require(len(status_fields)==1 and list(map(int,status_fields[0]))==row['NSpid'],'Original child raw NSpid status differs');require(int(row['stat_before'].split(' ',1)[0])==int(row['stat_after'].split(' ',1)[0])==row['host_pid']and int(row['stat_before'][row['stat_before'].rfind(')')+2:].split()[19])==int(row['stat_after'][row['stat_after'].rfind(')')+2:].split()[19])==row['start_ticks'],'Original raw child PID/start differs');require(all(type(row[k])is int and row[k]>0 for k in('host_pid','start_ticks','start_ticks_after'))and row['start_ticks']==row['start_ticks_after']and row['namespace']==proof['container_namespace']and row['exe']in(m['executable'],'/build/strata'),'Actual same-generation native executable/namespace owner differs');require(any(v['Destination']=='/build'and v['Source']==str(Path(m['executable']).parent)and v['RW']is False for v in before['Mounts']),'Exact actual SDK43 executable bind required');return {'container_id':before['Id'],'host_pid':row['host_pid'],'namespace_pid':proof['trace_native_pid'],'start_ticks':row['start_ticks'],'container_host_pid':proof['container_host_pid'],'process_memory_or_full_math_authority':False}

def decode_requests(root):
 root=Path(root);rows=c.read(root/'api-client/report.json')['results'];trace=[json.loads(line)for line in(root/'engine-token-trace.jsonl').read_text().splitlines()];begins=[r for r in trace if r['kind']=='engine_begin'];pending=list(range(8));requests=[]
 for begin in begins:
  matches=[i for i in pending if rows[i]['request']['messages']==begin['rendered_prompt']['messages']];require(matches,'Actual native/API prompt owner missing');i=min(matches);pending.remove(i);end=next(r for r in trace if r['kind']=='engine_end'and r['call']==begin['call']);message=rows[i]['response']['choices'][0]['message'];require(message.get('reasoning_content')in(None,'')and message.get('tool_calls')in(None,[]),'Thinkingfalse plain reply scope only');requests.append({'case':i,'repeat':begin['call'],'tokens':end['generated_ids'],'content':message['content']})
 require(len(requests)==8 and not pending,'All eight actual replies require independent decode');return requests

def recipe(root,m,pid,binding):
 directory=Path(root)/'native-reply-decode';name,cmd=life.contract.tokenizer_command(directory,m,pid,binding,HERE/'source43_api_tokenizer_worker_v1.py');return name,cmd+['/results/output-id-requests.json']

def execute(root,m,binding):
 root=Path(root);out=root/'native-reply-decode';require(not out.exists(),'New independent decode required');out.mkdir();requests=decode_requests(root);c.write(out/'tokenizer-plan.json',{'corpus_messages':[]});c.write(out/'output-id-requests.json',requests);name,cmd=recipe(root,m,os.getpid(),binding);c.write(out/'command.json',cmd);stdout=stderr=proc=None;failed=True;error=None
 try:
  proc=life.subprocess.Popen(cmd,stdout=life.subprocess.PIPE,stderr=life.subprocess.PIPE);stdout=life.Pump(proc.stdout,out/'stdout.log',lambda _:None);stderr=life.Pump(proc.stderr,out/'stderr.log',lambda _:None);require(proc.wait(timeout=120)==0,'Independent reply metadata tokenizer failed');failed=False
 except BaseException as exc:error=type(exc).__name__+': '+str(exc)
 finally:
  if proc is not None:
   missing=[(role,stream)for role,pump,stream in [('stdout',stdout,proc.stdout),('stderr',stderr,proc.stderr)]if pump is None]
   if missing:life.setup_failure_drain(out,name,cmd,m['runtime']['image'],binding,proc,missing,error)
   obj=life.safe_retire(out,name,cmd,m['runtime']['image'],binding,proc,failed);a=stdout.finish()if stdout else {'passed':False};b=stderr.finish()if stderr else {'passed':False};removal=life.remove_owned(out,obj,name,cmd,m['runtime']['image'],binding);c.write(out/'receipt.json',{'error':error,'return_code':proc.returncode,'terminal':obj,'stdout':a,'stderr':b,'removal':removal,'producer_pid':os.getpid(),'binding':binding,'finished_epoch':time.time()})
 require(error is None and proc is not None,'Original metadata launch failed '+str(error));return decoded_binding(root,m,os.getpid(),binding)

def decoded_binding(root,m,pid,binding):
 root=Path(root);out=root/'native-reply-decode';requests=decode_requests(root);require(canonical(c.read(out/'output-id-requests.json'))==canonical(requests)and c.read(out/'tokenizer-plan.json')=={'corpus_messages':[]},'Exact original independent decode input changed');name,cmd=recipe(root,m,pid,binding);require(canonical(c.read(out/'command.json'))==canonical(cmd),'Actual metadata command differs');receipt=c.read(out/'receipt.json');obj=receipt['terminal'];life.contract.inspection(obj,name,cmd,m['runtime']['image'],binding,True);life.terminal(obj['State']);require(c.absent(name),'Actual exact metadata container absence required');require(type(receipt['return_code'])is int and receipt['return_code']==0 and receipt['error']is None and receipt['producer_pid']==pid and receipt['binding']==binding and receipt['removal']['removed']is True and receipt['removal']['recovery_used']is False,'Original metadata lifecycle/owner failed');
 for role in('stdout','stderr'):
  row=receipt[role];require(row['passed']is True and row['eof']is True and row['retired']is True and row['errors']==[]and row['sha256']==c.sha(out/(role+'.log')),'Actual metadata pipe/EOF differs')
 observed=c.read(out/'tokenizer-fixtures.json');manifest=c.read(root/'artifact-identity.json');decoded_output_binding(requests,observed,manifest)
 return {'passed':True,'actual_replies':8,'current_original_tokenizer_decoded_native_ID_text':True,'requests_sha256':c.sha(out/'output-id-requests.json'),'decoded_sha256':c.sha(out/'tokenizer-fixtures.json'),'receipt_sha256':c.sha(out/'receipt.json')}

def decoded_output_binding(requests,observed,manifest):
 require(observed['actual_GPU_touch']is False and observed['actual_model_payload_read']is False and observed['fixtures']==[]and observed['tokenizer_file_sha256']==manifest['tokenizer_files']and len(observed['decoded_outputs'])==8,'Actual current original tokenizer roster required')
 for request,result in zip(requests,observed['decoded_outputs']):require(set(result)=={'case','repeat','text','matches'}and type(result['case'])is int and type(result['repeat'])is int and type(result['text'])is str and result['matches']is True,'Exact typed original decoded result required');require(result=={'case':request['case'],'repeat':request['repeat'],'text':request['content'],'matches':True},'Independent native IDs do not equal API content')
 return True

def parse_stat(raw):
 require(type(raw)is str and '('in raw and ')'in raw,'Actual original proc stat required');fields=raw[raw.rfind(')')+2:].split();require(len(fields)>=20,'Complete actual proc stat identity fields required');return {'pid':int(raw.split(' ',1)[0]),'ppid':int(fields[1]),'start':int(fields[19])}
